"use client";
import { ImageTrail } from "@/components/application/animations/expanded/pointer/image-trail";

export default function Example() {
  return (
    <ImageTrail
      images={["/assets/zeus/hero_run_02.jpg","/assets/zeus/hero_profile_02.jpg","/assets/zeus/action_cyclist-climb_02.jpg","/assets/zeus/action_leap_01.jpg","/assets/zeus/product_shoe_01.jpg"]}
      threshold={50}
      delay={40}
      imageWidth={180}
      imageHeight={240}
      entranceDuration={0.35}
      exitDuration={0.7}
      exitDelay={0.55}
      rotation={10}
    >
